/* ---------- attack detection ---------- */
int is_attacked(int sq, int by) {
    int s;
    if (by == WHITE) {
        s = sq - 15; if (!OFFBOARD(s) && board[s] == MK(WHITE,PAWN)) return 1;
        s = sq - 17; if (!OFFBOARD(s) && board[s] == MK(WHITE,PAWN)) return 1;
    } else {
        s = sq + 15; if (!OFFBOARD(s) && board[s] == MK(BLACK,PAWN)) return 1;
        s = sq + 17; if (!OFFBOARD(s) && board[s] == MK(BLACK,PAWN)) return 1;
    }
    int kn = MK(by,KNIGHT), kg = MK(by,KING), bi = MK(by,BISHOP), ro = MK(by,ROOK), qu = MK(by,QUEEN);
    for (int i = 0; i < 8; i++) {
        s = sq + knight_off[i]; if (!OFFBOARD(s) && board[s] == kn) return 1;
        s = sq + king_off[i]; if (!OFFBOARD(s) && board[s] == kg) return 1;
    }
    for (int i = 0; i < 4; i++) {
        s = sq + bishop_off[i];
        while (!OFFBOARD(s)) {
            if (board[s]) { if (board[s] == bi || board[s] == qu) return 1; break; }
            s += bishop_off[i];
        }
        s = sq + rook_off[i];
        while (!OFFBOARD(s)) {
            if (board[s]) { if (board[s] == ro || board[s] == qu) return 1; break; }
            s += rook_off[i];
        }
    }
    return 0;
}

/* ---------- move generation ---------- */
typedef struct { int m; int score; } Move;

static inline void add(Move *list, int *n, int m) { list[*n].m = m; list[*n].score = 0; (*n)++; }

int gen_moves(Move *list, int captures_only) {
    int n = 0;
    int fwd = side == WHITE ? 16 : -16;
    int startrank = side == WHITE ? 1 : 6;
    int promrank = side == WHITE ? 6 : 1;
    for (int sq = 0; sq < 128; sq++) {
        if (OFFBOARD(sq)) continue;
        int p = board[sq];
        if (!p || COLOR(p) != side) continue;
        int t = TYPE(p);
        if (t == PAWN) {
            int to = sq + fwd;
            if (!OFFBOARD(to) && board[to] == EMPTY) {
                if (RANKOF(sq) == promrank) {
                    add(list, &n, MOVE(sq,to,QUEEN,0,0));
                    if (!captures_only) {
                        add(list, &n, MOVE(sq,to,ROOK,0,0));
                        add(list, &n, MOVE(sq,to,BISHOP,0,0));
                        add(list, &n, MOVE(sq,to,KNIGHT,0,0));
                    }
                } else if (!captures_only) {
                    add(list, &n, MOVE(sq,to,0,0,0));
                    if (RANKOF(sq) == startrank && board[to+fwd] == EMPTY)
                        add(list, &n, MOVE(sq,to+fwd,0,F_DPUSH,0));
                }
            }
            for (int d = -1; d <= 1; d += 2) {
                to = sq + fwd + d;
                if (OFFBOARD(to)) continue;
                if (board[to] && COLOR(board[to]) != side) {
                    int cap = TYPE(board[to]);
                    if (RANKOF(sq) == promrank) {
                        add(list, &n, MOVE(sq,to,QUEEN,0,cap));
                        if (!captures_only) {
                            add(list, &n, MOVE(sq,to,ROOK,0,cap));
                            add(list, &n, MOVE(sq,to,BISHOP,0,cap));
                            add(list, &n, MOVE(sq,to,KNIGHT,0,cap));
                        }
                    } else add(list, &n, MOVE(sq,to,0,0,cap));
                } else if (to == ep && ep != -1) {
                    add(list, &n, MOVE(sq,to,0,F_EP,PAWN));
                }
            }
        } else if (t == KNIGHT || t == KING) {
            const int *off = t == KNIGHT ? knight_off : king_off;
            for (int i = 0; i < 8; i++) {
                int to = sq + off[i];
                if (OFFBOARD(to)) continue;
                if (board[to] == EMPTY) { if (!captures_only) add(list, &n, MOVE(sq,to,0,0,0)); }
                else if (COLOR(board[to]) != side) add(list, &n, MOVE(sq,to,0,0,TYPE(board[to])));
            }
            if (t == KING && !captures_only) {
                if (side == WHITE) {
                    if ((castle & 1) && board[SQ(5,0)] == EMPTY && board[SQ(6,0)] == EMPTY &&
                        board[SQ(7,0)] == MK(WHITE,ROOK) &&
                        !is_attacked(SQ(4,0),BLACK) && !is_attacked(SQ(5,0),BLACK))
                        add(list, &n, MOVE(SQ(4,0),SQ(6,0),0,F_CASTLE,0));
                    if ((castle & 2) && board[SQ(3,0)] == EMPTY && board[SQ(2,0)] == EMPTY && board[SQ(1,0)] == EMPTY &&
                        board[SQ(0,0)] == MK(WHITE,ROOK) &&
                        !is_attacked(SQ(4,0),BLACK) && !is_attacked(SQ(3,0),BLACK))
                        add(list, &n, MOVE(SQ(4,0),SQ(2,0),0,F_CASTLE,0));
                } else {
                    if ((castle & 4) && board[SQ(5,7)] == EMPTY && board[SQ(6,7)] == EMPTY &&
                        board[SQ(7,7)] == MK(BLACK,ROOK) &&
                        !is_attacked(SQ(4,7),WHITE) && !is_attacked(SQ(5,7),WHITE))
                        add(list, &n, MOVE(SQ(4,7),SQ(6,7),0,F_CASTLE,0));
                    if ((castle & 8) && board[SQ(3,7)] == EMPTY && board[SQ(2,7)] == EMPTY && board[SQ(1,7)] == EMPTY &&
                        board[SQ(0,7)] == MK(BLACK,ROOK) &&
                        !is_attacked(SQ(4,7),WHITE) && !is_attacked(SQ(3,7),WHITE))
                        add(list, &n, MOVE(SQ(4,7),SQ(2,7),0,F_CASTLE,0));
                }
            }
        } else {
            int nd = 0; const int *dirs;
            if (t == BISHOP) { dirs = bishop_off; nd = 4; }
            else if (t == ROOK) { dirs = rook_off; nd = 4; }
            else { dirs = king_off; nd = 8; }
            for (int i = 0; i < nd; i++) {
                int to = sq + dirs[i];
                while (!OFFBOARD(to)) {
                    if (board[to] == EMPTY) { if (!captures_only) add(list, &n, MOVE(sq,to,0,0,0)); }
                    else { if (COLOR(board[to]) != side) add(list, &n, MOVE(sq,to,0,0,TYPE(board[to]))); break; }
                    to += dirs[i];
                }
            }
        }
    }
    return n;
}

/* ---------- make / unmake ---------- */
void unmake_move(void);

int make_move(int m) {
    int from = FROM(m), to = TO(m), fl = FLAGS(m), pr = PROMO(m);
    int p = board[from];
    Undo *u = &undo_stack[hist_count];
    u->captured = board[to]; u->ep = ep; u->castle = castle; u->fifty = fifty; u->key = hashkey; u->move = m;
    hist_keys[hist_count] = hashkey; hist_count++;
    if (ep != -1) hashkey ^= zep[ep];
    hashkey ^= zcastle[castle];
    fifty++;
    if (u->captured) { hashkey ^= zpiece[u->captured][to]; fifty = 0; }
    board[from] = EMPTY; hashkey ^= zpiece[p][from];
    int np = pr ? MK(side,pr) : p;
    board[to] = np; hashkey ^= zpiece[np][to];
    if (TYPE(p) == PAWN) fifty = 0;
    ep = -1;
    if (fl == F_EP) {
        int capsq = side == WHITE ? to - 16 : to + 16;
        hashkey ^= zpiece[board[capsq]][capsq]; board[capsq] = EMPTY;
    } else if (fl == F_DPUSH) {
        ep = side == WHITE ? from + 16 : from - 16;
    } else if (fl == F_CASTLE) {
        int rf, rt;
        if (to == SQ(6,0)) { rf = SQ(7,0); rt = SQ(5,0); }
        else if (to == SQ(2,0)) { rf = SQ(0,0); rt = SQ(3,0); }
        else if (to == SQ(6,7)) { rf = SQ(7,7); rt = SQ(5,7); }
        else { rf = SQ(0,7); rt = SQ(3,7); }
        int r = board[rf];
        board[rf] = EMPTY; board[rt] = r;
        hashkey ^= zpiece[r][rf]; hashkey ^= zpiece[r][rt];
    }
    castle &= castle_mask[from] & castle_mask[to];
    hashkey ^= zcastle[castle];
    if (ep != -1) hashkey ^= zep[ep];
    if (TYPE(p) == KING) kingsq[side] = to;
    side ^= 1; hashkey ^= zside;
    ply++;
    if (is_attacked(kingsq[side^1], side)) { unmake_move(); return 0; }
    return 1;
}

void unmake_move(void) {
    hist_count--; ply--;
    Undo *u = &undo_stack[hist_count];
    int m = u->move;
    side ^= 1;
    int from = FROM(m), to = TO(m), fl = FLAGS(m), pr = PROMO(m);
    int p = board[to];
    if (pr) p = MK(side,PAWN);
    board[from] = p; board[to] = u->captured;
    if (fl == F_EP) {
        int capsq = side == WHITE ? to - 16 : to + 16;
        board[capsq] = MK(side^1,PAWN);
    } else if (fl == F_CASTLE) {
        int rf, rt;
        if (to == SQ(6,0)) { rf = SQ(7,0); rt = SQ(5,0); }
        else if (to == SQ(2,0)) { rf = SQ(0,0); rt = SQ(3,0); }
        else if (to == SQ(6,7)) { rf = SQ(7,7); rt = SQ(5,7); }
        else { rf = SQ(0,7); rt = SQ(3,7); }
        board[rf] = board[rt]; board[rt] = EMPTY;
    }
    if (TYPE(p) == KING) kingsq[side] = from;
    ep = u->ep; castle = u->castle; fifty = u->fifty; hashkey = u->key;
}

void make_null(void) {
    Undo *u = &undo_stack[hist_count];
    u->ep = ep; u->key = hashkey; u->move = 0; u->fifty = fifty; u->castle = castle; u->captured = 0;
    hist_keys[hist_count] = hashkey; hist_count++;
    if (ep != -1) hashkey ^= zep[ep];
    ep = -1; side ^= 1; hashkey ^= zside; ply++;
}
void unmake_null(void) {
    hist_count--; ply--;
    Undo *u = &undo_stack[hist_count];
    side ^= 1; ep = u->ep; hashkey = u->key; fifty = u->fifty;
}

/* ---------- FEN ---------- */
void set_fen(const char *fen) {
    for (int s = 0; s < 128; s++) board[s] = EMPTY;
    int r = 7, f = 0;
    const char *c = fen;
    while (*c && *c != ' ') {
        if (*c == '/') { r--; f = 0; }
        else if (*c >= '1' && *c <= '8') f += *c - '0';
        else {
            int col = (*c >= 'a') ? BLACK : WHITE;
            char l = *c | 32; int t = 0;
            switch (l) { case 'p': t=PAWN; break; case 'n': t=KNIGHT; break; case 'b': t=BISHOP; break;
                case 'r': t=ROOK; break; case 'q': t=QUEEN; break; case 'k': t=KING; break; }
            board[SQ(f,r)] = MK(col,t);
            if (t == KING) kingsq[col] = SQ(f,r);
            f++;
        }
        c++;
    }
    while (*c == ' ') c++;
    side = (*c == 'b') ? BLACK : WHITE;
    while (*c && *c != ' ') c++; while (*c == ' ') c++;
    castle = 0;
    while (*c && *c != ' ') {
        if (*c == 'K') castle |= 1; else if (*c == 'Q') castle |= 2;
        else if (*c == 'k') castle |= 4; else if (*c == 'q') castle |= 8;
        c++;
    }
    while (*c == ' ') c++;
    ep = -1;
    if (*c && *c != '-') { ep = SQ(c[0]-'a', c[1]-'1'); c += 2; } else if (*c) c++;
    while (*c == ' ') c++;
    fifty = 0;
    if (*c) fifty = atoi(c);
    hashkey = compute_key();
    hist_count = 0; ply = 0;
}

/* ---------- eval ---------- */
int evaluate(void) {
    int mg[2] = {0,0}, eg[2] = {0,0}, phase = 0;
    int bishops[2] = {0,0};
    int pawns[2][16]; int np[2] = {0,0};
    for (int sq = 0; sq < 128; sq++) {
        if (OFFBOARD(sq)) continue;
        int p = board[sq]; if (!p) continue;
        int c = COLOR(p), t = TYPE(p);
        int s64 = SQ64(sq);
        int idx = c == WHITE ? (s64 ^ 56) : s64;
        mg[c] += mg_value[t] + mg_table[t][idx];
        eg[c] += eg_value[t] + eg_table[t][idx];
        phase += phase_inc[t];
        if (t == BISHOP) bishops[c]++;
        if (t == PAWN && np[c] < 16) pawns[c][np[c]++] = sq;
    }
    for (int c = 0; c < 2; c++) {
        if (bishops[c] >= 2) { mg[c] += 30; eg[c] += 50; }
        for (int i = 0; i < np[c]; i++) {
            int sq = pawns[c][i], f = FILEOF(sq), r = RANKOF(sq);
            int passed = 1;
            for (int j = 0; j < np[c^1] && passed; j++) {
                int osq = pawns[c^1][j], of = FILEOF(osq), orr = RANKOF(osq);
                if (of >= f-1 && of <= f+1) {
                    if (c == WHITE ? orr > r : orr < r) passed = 0;
                }
            }
            /* doubled */
            for (int j = 0; j < np[c]; j++) if (j != i && FILEOF(pawns[c][j]) == f) { mg[c] -= 8; eg[c] -= 12; break; }
            /* isolated */
            int iso = 1;
            for (int j = 0; j < np[c]; j++) { int of = FILEOF(pawns[c][j]); if (of == f-1 || of == f+1) { iso = 0; break; } }
            if (iso) { mg[c] -= 10; eg[c] -= 15; }
            if (passed) {
                int rr = c == WHITE ? r : 7 - r;
                mg[c] += passed_mg[rr]; eg[c] += passed_eg[rr];
            }
        }
    }
    if (phase > 24) phase = 24;
    int score = ((mg[WHITE]-mg[BLACK]) * phase + (eg[WHITE]-eg[BLACK]) * (24-phase)) / 24;
    score += side == WHITE ? 10 : -10;
    return side == WHITE ? score : -score;
}

/* ---------- TT ---------- */
typedef struct { u64 key; int move; short score; unsigned char depth; unsigned char flag; } TTEntry;
#define TT_SIZE (1<<23)
#define TT_EXACT 1
#define TT_ALPHA 2
#define TT_BETA 3
TTEntry *tt;

void tt_store(int depth, int score, int flag, int move) {
    TTEntry *e = &tt[hashkey & (TT_SIZE-1)];
    if (e->key == hashkey && e->depth > depth && flag != TT_EXACT) return;
    if (score > MATE - 1000) score += ply; else if (score < -MATE + 1000) score -= ply;
    e->key = hashkey; e->move = move; e->score = score; e->depth = depth; e->flag = flag;
}
int tt_probe(int depth, int alpha, int beta, int *move, int *score) {
    TTEntry *e = &tt[hashkey & (TT_SIZE-1)];
    if (e->key != hashkey) { *move = 0; return 0; }
    *move = e->move;
    if (e->depth < depth) return 0;
    int s = e->score;
    if (s > MATE - 1000) s -= ply; else if (s < -MATE + 1000) s += ply;
    if (e->flag == TT_EXACT) { *score = s; return 1; }
    if (e->flag == TT_ALPHA && s <= alpha) { *score = alpha; return 1; }
    if (e->flag == TT_BETA && s >= beta) { *score = beta; return 1; }
    return 0;
}

/* ---------- search ---------- */
long long nodes;
int stop_search;
long long start_time, time_limit;
int root_side;
int killers[MAXPLY][2];
int history[2][128][128];
int contempt = 50;

long long now_ms(void) {
    struct timeval tv; gettimeofday(&tv, NULL);
    return (long long)tv.tv_sec * 1000 + tv.tv_usec / 1000;
}

int is_repetition(void) {
    for (int i = hist_count - 2; i >= 0 && i >= hist_count - fifty - 1; i -= 2)
        if (hist_keys[i] == hashkey) return 1;
    return 0;
}
int draw_score(void) { return side == root_side ? -contempt : contempt; }

void score_moves(Move *list, int n, int ttmove) {
    for (int i = 0; i < n; i++) {
        int m = list[i].m;
        if (m == ttmove) list[i].score = 1000000;
        else if (CAPT(m) || PROMO(m)) {
            int victim = CAPT(m), attacker = TYPE(board[FROM(m)]);
            list[i].score = 100000 + victim * 100 - attacker + (PROMO(m) == QUEEN ? 500 : 0);
        } else if (m == killers[ply][0]) list[i].score = 90000;
        else if (m == killers[ply][1]) list[i].score = 80000;
        else list[i].score = history[side][FROM(m)][TO(m)];
    }
}
int pick(Move *list, int n, int i) {
    int best = i;
    for (int j = i + 1; j < n; j++) if (list[j].score > list[best].score) best = j;
    Move t = list[i]; list[i] = list[best]; list[best] = t;
    return list[i].m;
}

void check_time(void) {
    if ((nodes & 2047) == 0 && now_ms() - start_time >= time_limit) stop_search = 1;
}

int quiesce(int alpha, int beta) {
    nodes++; check_time();
    if (stop_search) return 0;
    int stand = evaluate();
    if (stand >= beta) return beta;
    if (stand > alpha) alpha = stand;
    if (ply >= MAXPLY - 1) return stand;
    Move list[256];
    int n = gen_moves(list, 1);
    score_moves(list, n, 0);
    for (int i = 0; i < n; i++) {
        int m = pick(list, n, i);
        /* delta pruning */
        if (!PROMO(m) && stand + mg_value[CAPT(m)] + 200 < alpha) continue;
        if (!make_move(m)) continue;
        int score = -quiesce(-beta, -alpha);
        unmake_move();
        if (stop_search) return 0;
        if (score >= beta) return beta;
        if (score > alpha) alpha = score;
    }
    return alpha;
}

int has_non_pawn(int c) {
    for (int sq = 0; sq < 128; sq++) {
        if (OFFBOARD(sq)) continue;
        int p = board[sq];
        if (p && COLOR(p) == c && TYPE(p) != PAWN && TYPE(p) != KING) return 1;
    }
    return 0;
}

int search(int alpha, int beta, int depth, int do_null) {
    int in_check = is_attacked(kingsq[side], side^1);
    if (in_check) depth++;
    if (depth <= 0) return quiesce(alpha, beta);
    nodes++; check_time();
    if (stop_search) return 0;
    if (ply >= MAXPLY - 1) return evaluate();
    if (is_repetition() || fifty >= 100) return draw_score();

    /* mate distance pruning */
    if (alpha < -MATE + ply) alpha = -MATE + ply;
    if (beta > MATE - ply - 1) beta = MATE - ply - 1;
    if (alpha >= beta) return alpha;

    int ttmove = 0, ttscore;
    if (tt_probe(depth, alpha, beta, &ttmove, &ttscore)) return ttscore;

    int pv_node = beta - alpha > 1;
    int stat = evaluate();

    if (!pv_node && !in_check) {
        /* reverse futility */
        if (depth <= 4 && stat - 110 * depth >= beta) return stat;
        /* null move */
        if (do_null && depth >= 3 && stat >= beta && has_non_pawn(side)) {
            int R = 2 + depth / 4;
            make_null();
            int score = -search(-beta, -beta + 1, depth - 1 - R, 0);
            unmake_null();
            if (stop_search) return 0;
            if (score >= beta) return beta;
        }
    }

    Move list[256];
    int n = gen_moves(list, 0);
    score_moves(list, n, ttmove);
    int legal = 0, searched = 0, best_move = 0, flag = TT_ALPHA;
    int best_score = -INF;
    for (int i = 0; i < n; i++) {
        int m = pick(list, n, i);
        if (!make_move(m)) continue;
        legal++;
        int is_quiet = !CAPT(m) && !PROMO(m);
        int score;
        if (searched == 0) {
            score = -search(-beta, -alpha, depth - 1, 1);
        } else {
            int red = 0;
            if (is_quiet && depth >= 3 && searched >= 3 && !in_check) {
                red = 1 + (searched > 8) + (depth > 6 && searched > 14);
                if (pv_node) red--;
                if (red < 0) red = 0;
            }
            score = -search(-alpha - 1, -alpha, depth - 1 - red, 1);
            if (score > alpha && red) score = -search(-alpha - 1, -alpha, depth - 1, 1);
            if (score > alpha && score < beta) score = -search(-beta, -alpha, depth - 1, 1);
        }
        unmake_move();
        if (stop_search) return 0;
        searched++;
        if (score > best_score) { best_score = score; best_move = m; }
        if (score > alpha) {
            alpha = score; flag = TT_EXACT;
            if (is_quiet) {
                history[side][FROM(m)][TO(m)] += depth * depth;
                if (history[side][FROM(m)][TO(m)] > 60000)
                    for (int a = 0; a < 128; a++) for (int b = 0; b < 128; b++) history[side][a][b] /= 2;
            }
            if (score >= beta) {
                if (is_quiet && killers[ply][0] != m) { killers[ply][1] = killers[ply][0]; killers[ply][0] = m; }
                tt_store(depth, beta, TT_BETA, m);
                return beta;
            }
        }
    }
    if (legal == 0) return in_check ? -MATE + ply : draw_score();
    tt_store(depth, alpha, flag, best_move);
    return alpha;
}

char *move_str(int m, char *buf) {
    buf[0] = 'a' + FILEOF(FROM(m)); buf[1] = '1' + RANKOF(FROM(m));
    buf[2] = 'a' + FILEOF(TO(m)); buf[3] = '1' + RANKOF(TO(m));
    int k = 4;
    if (PROMO(m)) buf[k++] = " pnbrqk"[PROMO(m)];
    buf[k] = 0;
    return buf;
}

int parse_move(const char *s) {
    Move list[256];
    int n = gen_moves(list, 0);
    int from = SQ(s[0]-'a', s[1]-'1'), to = SQ(s[2]-'a', s[3]-'1');
    int pr = 0;
    if (s[4] && s[4] != ' ' && s[4] != '\n') {
        switch (s[4]) { case 'q': pr=QUEEN; break; case 'r': pr=ROOK; break; case 'b': pr=BISHOP; break; case 'n': pr=KNIGHT; break; }
    }
    for (int i = 0; i < n; i++) {
        int m = list[i].m;
        if (FROM(m) == from && TO(m) == to && PROMO(m) == pr) return m;
    }
    return 0;
}

void search_root(int max_depth, long long movetime) {
    char buf[8];
    start_time = now_ms(); time_limit = movetime; stop_search = 0; nodes = 0;
    root_side = side; ply = 0;
    memset(killers, 0, sizeof(killers));
    for (int c = 0; c < 2; c++) for (int a = 0; a < 128; a++) for (int b = 0; b < 128; b++) history[c][a][b] /= 8;
    Move list[256];
    int n = gen_moves(list, 0);
    Move legal[256]; int nl = 0;
    for (int i = 0; i < n; i++) if (make_move(list[i].m)) { unmake_move(); legal[nl].m = list[i].m; legal[nl].score = 0; nl++; }
    if (nl == 0) { printf("bestmove 0000\n"); fflush(stdout); return; }
    int best = legal[0].m;
    int last_score = 0;
    for (int depth = 1; depth <= max_depth; depth++) {
        int alpha = -INF, beta = INF;
        int iter_best = 0, iter_score = -INF;
        /* order: previous best first, then by previous iteration scores */
        for (int i = 0; i < nl; i++) if (legal[i].m == best) legal[i].score = 10000000;
        for (int i = 0; i < nl; i++) {
            int m = pick(legal, nl, i);
            make_move(m);
            int score;
            if (i == 0) score = -search(-beta, -alpha, depth - 1, 1);
            else {
                score = -search(-alpha - 1, -alpha, depth - 1, 1);
                if (score > alpha && !stop_search) score = -search(-beta, -alpha, depth - 1, 1);
            }
            unmake_move();
            if (stop_search) break;
            legal[i].score = score;
            if (score > iter_score) { iter_score = score; iter_best = m; }
            if (score > alpha) alpha = score;
        }
        if (stop_search) {
            if (iter_best && iter_score > -INF && iter_best != best && iter_score >= last_score) best = iter_best;
            break;
        }
        best = iter_best; last_score = iter_score;
        long long el = now_ms() - start_time;
        printf("info depth %d score cp %d nodes %lld time %lld pv %s\n", depth, iter_score, nodes, el, move_str(best, buf));
        fflush(stdout);
        if (iter_score > MATE - 100 || iter_score < -MATE + 100) break;
        if (el * 2 > movetime) break;
    }
    printf("bestmove %s\n", move_str(best, buf));
    fflush(stdout);
}

u64 perft(int depth) {
    if (depth == 0) return 1;
    Move list[256];
    int n = gen_moves(list, 0);
    u64 cnt = 0;
    for (int i = 0; i < n; i++) {
        if (!make_move(list[i].m)) continue;
        cnt += perft(depth - 1);
        unmake_move();
    }
    return cnt;
}

